INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1536360-che360', 'stk-giant_genius1', 'CHE 360', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته\n\nبعد إذن الأخوة المشرفين\n\nيا ليت تعطونا فكرة عن المادة و طبيعتها و وش تدرسون فيها\n\nو اللي عنده أي ملف سواء سلايدات او اختبارات قديمة اوهومورك او كويز او اي شي غيرها ممكن يساعدنا يا ليت ينزله لنا هنا و لا عليكم أمر\n\nمع التحية مقدما", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-360-numerical-methods-in-chemical-engineering/184929/1", "user": "Giant_Genius1", "ts": 1676255524000, "tid": 184929, "pn": 1}}', 1676255524000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-che360', 'stk-ahmed1', 'CHE 360', 'doc', '{"docs": [{"id": "stk-dr-f118698", "n": "Dr. Nayef Al-Saifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 360 - TERM 222\n\nالتحضير : بداية الكلاس، بشكل شبه يومي.\n\nطريقة الشرح : ممتازة وواضحة ويبسط المواضيع بطريقته، يحاول يوريك فايدة اللي تدرسه وكيف تستخدمه في الماتلاب والشي ذا حلو عشان تعرفه لكنه للاسف غير مطلوب منك في الكورس.\n\nالكويزات : سهلة.\n\nالمياجر: كومن.\nالفاينلات :كومن.\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : المادة سهلة وخفيفة ودكتور نايف الله يجزيه الخير بسطها اكثر، ولكن فيه دكاترة متمكنين في هذا الكورس اكثر، نصيحتي انك تنزل عند اللي يناسبك وقته في هالمادة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536742-che360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nayef-al-saifi/118698/31", "user": "Ahmed1", "ts": 1686158004000, "tid": 118698, "pn": 31}}]}', 1686158004000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
